// POCKET-BRAIN service worker (generated by scripts/build-sw.mjs; do not edit dist/sw.js).
// Policy: cache-first for the precached app shell, everything else goes straight to the network.
// Never touches cross-origin requests (Hugging Face model downloads) or api.github.com.
const VERSION = '__VERSION__';
const CACHE = 'pocket-brain-shell-' + VERSION;
const BASE = '__BASE__';
const PRECACHE = __PRECACHE__;
const PRECACHE_SET = new Set(PRECACHE);

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((k) => k.startsWith('pocket-brain-shell-') && k !== CACHE).map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Cross-origin (huggingface.co, api.github.com, ...): do not intercept at all.
  if (url.origin !== self.location.origin) return;
  if (url.hostname === 'api.github.com') return;
  // Only the precached shell is served from cache; ignore the query string (e.g. ?t=...).
  if (!PRECACHE_SET.has(url.pathname)) return;
  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(url.pathname).then((hit) => hit || fetch(req)),
    ),
  );
});
